let filterDepositV1 (contract: Contract) (fromBlock: BlockParameter) (toBlock: BlockParameter) =
    let filter = contract.GetEventBySignature("0x75f574baad88ac0a054ccfcae9abae0cbe7fa3ba47b3a8ecd5f125c90b4c3032").CreateFilterInput(fromBlock, toBlock)
    filter

let decodeDepositV1Event (contract: Contract) (log: FilterLog) : DepositV1Event =
    let decoded = contract.GetEventBySignature("0x75f574baad88ac0a054ccfcae9abae0cbe7fa3ba47b3a8ecd5f125c90b4c3032").DecodeAllEventsForEvent<DepositV1Event>([| log |])
    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryDepositV1 (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<DepositV1Event>>()
        let event = contract.GetEventBySignature("0x75f574baad88ac0a054ccfcae9abae0cbe7fa3ba47b3a8ecd5f125c90b4c3032")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<DepositV1Event>(decodeDepositV1Event contract log, log))
        return result
    }

